using System;using System.IO;using System.Diagnostics;using System.Threading;using System.Collections.Generic;using System.Web.Script.Serialization;
class MutsumiClientLauncher {
 static void Run(string exe,string args){Process.Start(new ProcessStartInfo(exe,args){UseShellExecute=false,CreateNoWindow=true,WindowStyle=ProcessWindowStyle.Hidden});}
 static bool Alive(string exe){foreach(var p in Process.GetProcessesByName(Path.GetFileNameWithoutExtension(exe))){try{if(p.MainModule.FileName.Equals(exe,StringComparison.OrdinalIgnoreCase)&&p.MainWindowHandle!=IntPtr.Zero)return true;}catch{}finally{p.Dispose();}}return false;}
 [STAThread]static void Main(){string root=AppDomain.CurrentDomain.BaseDirectory;try{var json=new JavaScriptSerializer();var c=json.Deserialize<Dictionary<string,object>>(File.ReadAllText(Path.Combine(root,@"data\mutsumi-install.json")));var f=json.Deserialize<Dictionary<string,object>>(File.ReadAllText(Path.Combine(root,@"data\follow-config.json")));string exe=(string)c["clientExe"];Run((string)f["launcherPath"],"--script \""+Path.Combine(root,@"widget\desktop\supervisor.ps1")+"\" --data \""+Path.Combine(root,"data")+"\"");if(Alive(exe))return;string ps=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.System),@"WindowsPowerShell\v1.0\powershell.exe");using(var p=Process.Start(new ProcessStartInfo(ps,"-NoLogo -NoProfile -NonInteractive -ExecutionPolicy RemoteSigned -File \""+Path.Combine(root,"Background-Start.ps1")+"\" -InstallRoot \""+root.TrimEnd('\\')+"\""){UseShellExecute=false,CreateNoWindow=true,WindowStyle=ProcessWindowStyle.Hidden})){for(int i=0;i<600&&!Alive(exe)&&!p.HasExited;i++)Thread.Sleep(100);}if(!Alive(exe))Process.Start(new ProcessStartInfo("explorer.exe","shell:AppsFolder\\"+(string)c["appId"]){UseShellExecute=true});}catch{try{File.WriteAllText(Path.Combine(root,"launch-error.txt"),"Managed launch failed. Run Status.ps1 for local diagnostics.");}catch{}}}
}
